//! Search-mode admission fixtures generated by the production query compiler.
use crate::auth::PrincipalCtx;
use crate::query::{Query, compile_query};
use crate::schema::SchemaDef;
use serde_json::json;

/// Render default/explicit mode selection and incompatible-option rejections.
pub fn render_search_modes_spec() -> Result<String, serde_json::Error> {
    let mut rows = Vec::new();
    for (id, trgm, search) in [
        ("default-tsquery", false, json!({})),
        ("explicit-tsquery", false, json!({"mode":"tsquery"})),
        ("trgm-enabled", true, json!({"mode":"trgm"})),
        ("trgm-not-enabled", false, json!({"mode":"trgm"})),
        (
            "trgm-snippet-rejected",
            true,
            json!({"mode":"trgm","snippet":true}),
        ),
        (
            "trgm-rank-mode-rejected",
            true,
            json!({"mode":"trgm","rankMode":"ts_rank_cd"}),
        ),
        (
            "tsquery-similarity-rejected",
            true,
            json!({"mode":"tsquery","minSimilarity":0.5}),
        ),
        (
            "trgm-similarity-min",
            true,
            json!({"mode":"trgm","minSimilarity":0}),
        ),
        (
            "trgm-similarity-max",
            true,
            json!({"mode":"trgm","minSimilarity":1}),
        ),
        (
            "trgm-similarity-negative",
            true,
            json!({"mode":"trgm","minSimilarity":-0.1}),
        ),
        (
            "trgm-similarity-too-high",
            true,
            json!({"mode":"trgm","minSimilarity":1.1}),
        ),
        ("tsquery-snippet", false, json!({"snippet":true})),
        ("empty-query-rejected", true, json!({"query":" "})),
        ("missing-index-rejected", true, json!({"index":"missing"})),
    ] {
        let schema_json = json!({"tables":{"items":{"fields":{"text":{"type":"string"}},"indexes":[{"name":"search_text","fields":["text"],"search":true,"trgm":trgm}]}}});
        let schema: SchemaDef = serde_json::from_value(schema_json.clone())?;
        let mut search_json = json!({"index":"search_text","query":"hello"});
        if let (Some(base), Some(extra)) = (search_json.as_object_mut(), search.as_object()) {
            base.extend(extra.clone());
        }
        let query_json = json!({"table":"items","search":search_json});
        let query: Query = serde_json::from_value(query_json.clone())?;
        let expect = match compile_query(
            "spec_search",
            &schema,
            &query,
            &PrincipalCtx::bypass(),
            false,
        ) {
            Ok(_) => json!({"accepted":true}),
            Err(error) => json!({"error":{"code":error.code}}),
        };
        rows.push(json!({"id":id,"schema":schema_json,"query":query_json,"expect":expect}));
    }
    let mut out = serde_json::to_string_pretty(&json!({
        "$comment":"GENERATED by make gen-spec-search-modes calling production query::compile_query / compile_search. Clients execute the same queries on an empty engine and assert admission or error codes, independent of search ranking algorithms.",
        "rows":rows
    }))?;
    out.push('\n');
    Ok(out)
}
